ValidationRule.errorConditionFormula:
AND (
    /* If owner is Changed */
    ISCHANGED(OwnerId),
    /* If the owner is user and not queue */
    LEFT(OwnerId,3) != '00G',
    OR(
        /* Country should be present for all users */
        Owner:User.Country = '',
        $User.Country = '',
        NOT (
            /* Owner country is present in allowed countries */
            CONTAINS (
                /* fetch allowed countries */
                VLOOKUP(
                    $ObjectType.CountryGroup__c.Fields.Countries_Allowed__c,
                    $ObjectType.CountryGroup__c.Fields.Name,
                    $User.Country
                ),
                Owner:User.Country
            )
        )
    )
)
